  removeParticipantFromMeet(state, { meetId, userId }) {
    if (state.activeMeets[meetId]) {
      state.activeMeets[meetId].participants = state.activeMeets[meetId].participants.filter(p => p !== userId)
    }
  },

  endActiveMeet(state, meetId) {
