    state.availableDevices = devices
  },

  setAudioTestActive(state, active) {
    state.isAudioTestActive = active
  },

  clearAllMeets(state) {
    state.activeMeets = {}
    state.incomingInvitations = {}
    state.currentMeetId = null
    state.meetStatus = 'idle'
    state.isMuted = false
  }
})

export const actions = actionTree(
