    state.joinRequests = {
      ...state.joinRequests,
      [key]: {
        meetId: request.meetId,
        from: request.from,
        fromName: request.fromName || request.from,
        fromAvatar: request.fromAvatar || '',
        timestamp: request.timestamp || Date.now()
      }
